import{_ as t,a as o,o as r,ai as a}from"./chunks/framework.BbOtTPsL.js";const u=JSON.parse('{"title":"Search Products","description":"","frontmatter":{"outline":false,"examples":[{"id":"search-by-keyword","title":"Search by keyword","description":"Use `?query=` to match against product SKU and name.","request":"curl -X GET \\"http://localhost/api/shop/products?query=hoodie&per_page=2\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"X-STOREFRONT-KEY: pk_storefront_xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx\\"\\n","response":"HTTP/1.1 200 OK\\nX-Total-Count: 3\\nX-Page: 1\\nX-Per-Page: 2\\nX-Total-Pages: 2\\n\\n[\\n  {\\n    \\"id\\": 1,\\n    \\"sku\\": \\"COASTALBREEZEMENSHOODIE\\",\\n    \\"type\\": \\"simple\\",\\n    \\"name\\": \\"Coastal Breeze Men\'s Blue Zipper Hoodie\\",\\n    \\"price\\": 100,\\n    \\"...\\": \\"...\\"\\n  }\\n]\\n","commonErrors":[{"error":"401 Unauthorized","cause":"Missing or invalid `X-STOREFRONT-KEY`","solution":"Send a valid storefront API key."}]},{"id":"filter-by-type","title":"Filter by product type","description":"Restrict to a single product type (e.g. all configurable products).","request":"curl -X GET \\"http://localhost/api/shop/products?type=configurable&per_page=10\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"X-STOREFRONT-KEY: pk_storefront_xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx\\"\\n","response":"HTTP/1.1 200 OK\\nX-Total-Count: 4\\nX-Page: 1\\nX-Per-Page: 10\\nX-Total-Pages: 1\\n\\n[\\n  { \\"id\\": 23, \\"sku\\": \\"NGJGAJSDGJ123123GJGJ\\", \\"type\\": \\"configurable\\", \\"name\\": \\"Luggage bags\\", \\"price\\": 0, \\"...\\": \\"...\\" }\\n]\\n"},{"id":"filter-by-category","title":"Filter by category","description":"Scope the listing to a single category. Pass either `category_id` (snake_case) or `categoryId` (camelCase).","request":"curl -X GET \\"http://localhost/api/shop/products?category_id=23&per_page=2\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"X-STOREFRONT-KEY: pk_storefront_xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx\\"\\n","response":"HTTP/1.1 200 OK\\nX-Total-Count: 14\\nX-Page: 1\\nX-Per-Page: 2\\nX-Total-Pages: 7\\n\\n[\\n  { \\"id\\": 279, \\"sku\\": \\"sofa2\\", \\"type\\": \\"simple\\", \\"name\\": \\"Imperial Velvet Comfort Sofa\\", \\"price\\": 4000, \\"...\\": \\"...\\" }\\n]\\n"},{"id":"filter-by-price","title":"Filter by price range","description":"Use `?price=from,to` (compound) or `?price_from=` + `?price_to=` (separate). Both are equivalent.","request":"curl -X GET \\"http://localhost/api/shop/products?price=10,200&per_page=2\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"X-STOREFRONT-KEY: pk_storefront_xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx\\"\\n","response":"HTTP/1.1 200 OK\\nX-Total-Count: 25\\nX-Page: 1\\nX-Per-Page: 2\\nX-Total-Pages: 13\\n\\n[\\n  { \\"id\\": 1,  \\"sku\\": \\"COASTALBREEZEMENSHOODIE\\", \\"type\\": \\"simple\\", \\"name\\": \\"Coastal Breeze Men\'s Blue Zipper Hoodie\\", \\"price\\": 100, \\"...\\": \\"...\\" },\\n  { \\"id\\": 2,  \\"sku\\": \\"PUREWHTSNEAK2023\\",       \\"type\\": \\"simple\\", \\"name\\": \\"PureStride Men\'s Classic White Sneakers\\", \\"price\\": 189, \\"...\\": \\"...\\" }\\n]\\n"},{"id":"filter-by-attribute","title":"Filter by attribute (color / size / brand / …)","description":"Pass any **filterable attribute code** as a query parameter. The value is the option ID. For multi-select, comma-separate the IDs.\\n\\nDiscover the available attribute codes and their option IDs via [`GET /api/shop/attributes`](/api/rest-api/shop/attributes/get-attributes).\\n","request":"curl -X GET \\"http://localhost/api/shop/products?color=3&per_page=2\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"X-STOREFRONT-KEY: pk_storefront_xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx\\"\\n","response":"HTTP/1.1 200 OK\\nX-Total-Count: 13\\nX-Page: 1\\nX-Per-Page: 2\\nX-Total-Pages: 7\\n\\n[\\n  { \\"id\\": 12, \\"sku\\": \\"...\\", \\"type\\": \\"simple\\", \\"name\\": \\"...\\", \\"price\\": 250, \\"...\\": \\"...\\" }\\n]\\n"},{"id":"sort-products","title":"Sort","description":"Use `?sort=` with a compound token like `name-asc`, `price-desc`, `created_at-desc`. Or pass `?sort=name&order=desc` for the bare-key + direction form.\\n","request":"curl -X GET \\"http://localhost/api/shop/products?sort=name-asc&per_page=2\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"X-STOREFRONT-KEY: pk_storefront_xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx\\"\\n","response":"HTTP/1.1 200 OK\\n\\n[\\n  { \\"id\\": 11, \\"name\\": \\"A Best Shooes\\", \\"price\\": 1, \\"...\\": \\"...\\" },\\n  { \\"id\\": 13, \\"name\\": \\"Acme Baby Cap\\", \\"price\\": 25, \\"...\\": \\"...\\" }\\n]\\n"},{"id":"filter-new-featured","title":"Filter new / featured","description":"Restrict to \\"new\\" or \\"featured\\" flagged products. Combine with other filters.","request":"curl -X GET \\"http://localhost/api/shop/products?new=1&featured=1&per_page=2\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"X-STOREFRONT-KEY: pk_storefront_xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx\\"\\n","response":"HTTP/1.1 200 OK\\n\\n[\\n  { \\"id\\": 1,  \\"name\\": \\"Coastal Breeze…\\", \\"new\\": true, \\"featured\\": true, \\"price\\": 100, \\"...\\": \\"...\\" },\\n  { \\"id\\": 2,  \\"name\\": \\"PureStride…\\",     \\"new\\": true, \\"featured\\": true, \\"price\\": 189, \\"...\\": \\"...\\" }\\n]\\n"},{"id":"combined-filters","title":"Combine filters","description":"Filters are AND-combined. The example below restricts to color = 3, in category 5, sorted by price descending.","request":"curl -X GET \\"http://localhost/api/shop/products?category_id=5&color=3&sort=price-desc&per_page=20\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"X-STOREFRONT-KEY: pk_storefront_xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx\\"\\n","response":"HTTP/1.1 200 OK\\nX-Total-Count: 6\\nX-Page: 1\\nX-Per-Page: 20\\nX-Total-Pages: 1\\n\\n[ … ]\\n"}]},"headers":[],"relativePath":"api/rest-api/shop/products/search-product.md","filePath":"api/rest-api/shop/products/search-product.md","lastUpdated":1782473079000}'),d={name:"api/rest-api/shop/products/search-product.md"};function s(i,e,n,c,p,l){return r(),o("div",null,e[0]||(e[0]=[a(`<h1 id="search-products" tabindex="-1">Search Products <a class="header-anchor" href="#search-products" aria-label="Permalink to &quot;Search Products&quot;">​</a></h1><p>The list endpoint at <code>GET /api/shop/products</code> doubles as the <strong>search &amp; filter</strong> endpoint. Every storefront facet — keyword search, category, price range, attribute filters, sort, &quot;new&quot; / &quot;featured&quot; — is just a query parameter. This page is the complete reference for those parameters.</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /api/shop/products</span></span></code></pre></div><p>Same URL as <a href="/api/rest-api/shop/products/get-products.html">Products</a>; the only difference is which query parameters you send.</p><h2 id="reserved-parameters" tabindex="-1">Reserved parameters <a class="header-anchor" href="#reserved-parameters" aria-label="Permalink to &quot;Reserved parameters&quot;">​</a></h2><p>These names are interpreted by the search/sort/pagination layer — never as attribute filters:</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>query</code></td><td>string</td><td>—</td><td>Search term. Matches against product SKU and product name.</td></tr><tr><td><code>sort</code></td><td>string</td><td>—</td><td>Sort token. Either compound (<code>name-asc</code>, <code>price-desc</code>) or a bare key paired with <code>order</code> (<code>sort=name&amp;order=desc</code>). See <a href="#sort-tokens">Sort tokens</a> below.</td></tr><tr><td><code>order</code></td><td>string</td><td><code>asc</code></td><td>Direction when <code>sort</code> is a bare key. Ignored if <code>sort</code> already has a <code>-asc</code> / <code>-desc</code> suffix.</td></tr><tr><td><code>page</code></td><td>integer</td><td><code>1</code></td><td>1-based page number.</td></tr><tr><td><code>per_page</code></td><td>integer</td><td><code>30</code></td><td>Items per page. Max <strong>50</strong>.</td></tr><tr><td><code>locale</code></td><td>string</td><td>—</td><td>Locale override (alternative to the <code>X-Locale</code> header).</td></tr><tr><td><code>channel</code></td><td>string</td><td>—</td><td>Channel override (alternative to the <code>X-Channel</code> header).</td></tr><tr><td><code>filter</code></td><td>string</td><td>—</td><td>JSON filter object — GraphQL parity. Example: <code>{&quot;color&quot;:{&quot;match&quot;:&quot;3&quot;,&quot;match_type&quot;:&quot;PARTIAL&quot;}}</code>. Most clients prefer the simpler <code>?&lt;attribute&gt;=&lt;id&gt;</code> shorthand.</td></tr><tr><td><code>type</code></td><td>string</td><td>—</td><td>Product type. One of <code>simple</code>, <code>configurable</code>, <code>bundle</code>, <code>grouped</code>, <code>virtual</code>, <code>downloadable</code>, <code>booking</code>.</td></tr><tr><td><code>category_id</code></td><td>integer</td><td>—</td><td>Filter by category ID. <code>categoryId</code> (camelCase) is also accepted.</td></tr><tr><td><code>price</code></td><td>string</td><td>—</td><td>Compound price range <code>from,to</code> (e.g. <code>10,200</code>).</td></tr><tr><td><code>price_from</code></td><td>number</td><td>—</td><td>Minimum price (inclusive). Equivalent to the lower bound of <code>price</code>.</td></tr><tr><td><code>price_to</code></td><td>number</td><td>—</td><td>Maximum price (inclusive). Equivalent to the upper bound of <code>price</code>.</td></tr><tr><td><code>new</code></td><td>boolean</td><td>—</td><td><code>1</code> to restrict to products with the &quot;new&quot; flag set.</td></tr><tr><td><code>featured</code></td><td>boolean</td><td>—</td><td><code>1</code> to restrict to products with the &quot;featured&quot; flag set.</td></tr></tbody></table><h2 id="attribute-filters-anything-else" tabindex="-1">Attribute filters (anything else) <a class="header-anchor" href="#attribute-filters-anything-else" aria-label="Permalink to &quot;Attribute filters (anything else)&quot;">​</a></h2><blockquote><p><strong>Any query parameter not listed above is treated as a filterable attribute.</strong> No schema changes are required when admins add new filterable attributes — the URL just works.</p></blockquote><table tabindex="0"><thead><tr><th>Pattern</th><th>Example</th><th>Effect</th></tr></thead><tbody><tr><td><code>?&lt;code&gt;=&lt;option_id&gt;</code></td><td><code>?color=3</code></td><td>Single option ID match</td></tr><tr><td><code>?&lt;code&gt;=id1,id2,…</code></td><td><code>?size=4,5,6</code></td><td>Multi-option (OR) match</td></tr><tr><td><code>?brand=N</code>, <code>?material=N</code></td><td><code>?material=12</code></td><td>Same shape — works for any filterable attribute</td></tr><tr><td><code>?filter[color]=3&amp;filter[size]=5</code></td><td>(Swagger UI form)</td><td>API Platform&#39;s bracket-syntax form. Same semantics as the bare-key form.</td></tr></tbody></table><p>To list which attributes are filterable and what their option IDs are, fetch <a href="/api/rest-api/shop/attributes/get-attributes.html"><code>GET /api/shop/attributes</code></a> and look for <code>isFilterable: 1</code>. Each attribute&#39;s <code>options[]</code> array has the IDs.</p><h2 id="sort-tokens" tabindex="-1">Sort tokens <a class="header-anchor" href="#sort-tokens" aria-label="Permalink to &quot;Sort tokens&quot;">​</a></h2><p>The compound form (<code>&lt;key&gt;-&lt;dir&gt;</code>) is recommended:</p><table tabindex="0"><thead><tr><th>Token</th><th>Sort by</th></tr></thead><tbody><tr><td><code>name-asc</code></td><td>Product name, A→Z</td></tr><tr><td><code>name-desc</code></td><td>Product name, Z→A</td></tr><tr><td><code>price-asc</code></td><td>Price, low→high</td></tr><tr><td><code>price-desc</code></td><td>Price, high→low</td></tr><tr><td><code>created_at-asc</code></td><td>Oldest first</td></tr><tr><td><code>created_at-desc</code></td><td>Newest first</td></tr><tr><td><code>updated_at-asc</code></td><td>Oldest update first</td></tr><tr><td><code>updated_at-desc</code></td><td>Most recently updated first</td></tr><tr><td><code>id-asc</code></td><td>Ascending ID (catalog order)</td></tr><tr><td><code>id-desc</code></td><td>Descending ID</td></tr></tbody></table><p>Alternative form: <code>?sort=name&amp;order=desc</code>. Pick one; mixing them isn&#39;t useful.</p><h2 id="combining-filters" tabindex="-1">Combining filters <a class="header-anchor" href="#combining-filters" aria-label="Permalink to &quot;Combining filters&quot;">​</a></h2><p>All filters are <strong>AND-combined</strong>. There is no OR across different filters — the only multi-value form is comma-separated values within a single attribute (<code>?size=4,5,6</code>).</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /api/shop/products?</span></span>
<span class="line"><span>  category_id=5</span></span>
<span class="line"><span>  &amp;color=3</span></span>
<span class="line"><span>  &amp;size=4,5</span></span>
<span class="line"><span>  &amp;price=10,200</span></span>
<span class="line"><span>  &amp;new=1</span></span>
<span class="line"><span>  &amp;sort=price-desc</span></span>
<span class="line"><span>  &amp;per_page=24</span></span></code></pre></div><h2 id="response" tabindex="-1">Response <a class="header-anchor" href="#response" aria-label="Permalink to &quot;Response&quot;">​</a></h2><p><code>200 OK</code> — JSON array of card-level product objects (same shape as <a href="/api/rest-api/shop/products/get-products.html#card-level-fields">Products</a>). Pagination headers always emitted.</p><blockquote><p>An empty filter result returns an empty array <code>[]</code> with <code>200 OK</code> and <code>X-Total-Count: 0</code>. It does <strong>not</strong> 404.</p></blockquote><h2 id="common-pitfalls" tabindex="-1">Common pitfalls <a class="header-anchor" href="#common-pitfalls" aria-label="Permalink to &quot;Common pitfalls&quot;">​</a></h2><ul><li>Sending <code>itemsPerPage</code> instead of <code>per_page</code> — the legacy API Platform name is <strong>not accepted</strong>.</li><li>Filtering by an attribute that isn&#39;t flagged <code>isFilterable=1</code> — the parameter is silently ignored.</li><li>Filtering by an attribute <em>code</em> but passing an option <em>label</em> (e.g. <code>?color=Red</code>) — values are matched against option <strong>IDs</strong>, not labels.</li><li>Combining <code>price</code> + <code>price_from</code>/<code>price_to</code> — pick one. The compound form wins if both are present.</li></ul><h2 id="related-resources" tabindex="-1">Related Resources <a class="header-anchor" href="#related-resources" aria-label="Permalink to &quot;Related Resources&quot;">​</a></h2><ul><li><a href="/api/rest-api/shop/products/get-products.html">Products</a> — same endpoint with no filters</li><li><a href="/api/rest-api/shop/products/get-product.html">Single Product</a> — fetch one product after the user picks a result</li><li><a href="/api/rest-api/shop/categories/get-categories.html">Categories</a> — discover category IDs for <code>?category_id=N</code></li><li><a href="/api/rest-api/shop/attributes/get-attributes.html">Attributes</a> — discover filterable attribute codes</li><li><a href="/api/rest-api/introduction.html#pagination">Pagination</a></li></ul>`,26)]))}const h=t(d,[["render",s]]);export{u as __pageData,h as default};
